namespace Torii.Api.Models;

public class Ticket
{
    /// <summary>
    /// Primary key in the <c>TI000001</c> format, generated by PostgreSQL on insert
    /// (<c>TicketNumbers</c> sequence + <c>next_ticket_number()</c> function, see ToriiDbContext).
    /// Do not assign it: left <c>null</c>, EF reads it back after <c>SaveChanges</c>.
    /// </summary>
    public string Number { get; private set; } = null!;
    public string Title { get; set; } = null!;
    public ICollection<TicketChannel>? Channels { get; set; }

    /// <summary>User who created the ticket (null only for legacy rows without any message).</summary>
    public long? CreatedById { get; set; }
    public User? CreatedBy { get; set; }

    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;
}
